package com.example.internmanagement.dao;

import com.example.internmanagement.util.DBConnection;
import java.sql.*;
import java.time.*;
import java.util.*;

public class MeetingDAO {
    public List<Map<String,Object>> list(long userId, boolean hr, String status) throws SQLException {
        String sql="SELECT m.*,u.full_name creator_name,COUNT(mr.intern_profile_id) recipient_count,"+
                "SUM(mr.last_email_status='SENT') sent_count,SUM(mr.last_email_status IN ('FAILED','FAILED_FINAL')) failed_count " +
                "FROM meetings m JOIN users u ON u.id=m.creator_user_id LEFT JOIN meeting_recipients mr ON mr.meeting_id=m.id " +
                "WHERE (? OR m.creator_user_id=?) AND (?='ALL' OR m.status=?) GROUP BY m.id,u.full_name " +
                "ORDER BY m.meeting_date DESC,m.start_time DESC LIMIT 200";
        try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){
            s.setBoolean(1,hr);s.setLong(2,userId);s.setString(3,status);s.setString(4,status);return rows(s);
        }
    }
    public List<Map<String,Object>> interns(long userId, boolean hr) throws SQLException {
        String sql="SELECT ip.id,ip.intern_code,u.full_name,u.email,p.program_name FROM intern_profiles ip JOIN users u ON u.id=ip.user_id " +
                "LEFT JOIN internship_programs p ON p.id=ip.program_id LEFT JOIN mentors m ON m.id=ip.mentor_id " +
                "WHERE ip.internship_status='ACTIVE' AND u.status='ACTIVE' AND (? OR m.user_id=?) ORDER BY p.program_name,u.full_name";
        try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setBoolean(1,hr);s.setLong(2,userId);return rows(s);}
    }
    public Map<String,Object> find(long id,long userId,boolean hr) throws SQLException {
        String sql="SELECT m.*,u.full_name creator_name FROM meetings m JOIN users u ON u.id=m.creator_user_id WHERE m.id=? AND (? OR m.creator_user_id=?)";
        try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setLong(1,id);s.setBoolean(2,hr);s.setLong(3,userId);try(ResultSet r=s.executeQuery()){return r.next()?row(r):null;}}
    }
    public List<Map<String,Object>> recipients(long meetingId) throws SQLException {
        try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("SELECT mr.*,ip.intern_code FROM meeting_recipients mr JOIN intern_profiles ip ON ip.id=mr.intern_profile_id WHERE mr.meeting_id=? ORDER BY mr.recipient_name")){s.setLong(1,meetingId);return rows(s);}
    }
    public List<Map<String,Object>> conflicts(Connection c, Collection<Long> ids, LocalDate date, LocalTime start, LocalTime end, Long excluded) throws SQLException {
        if(ids.isEmpty())return List.of();String marks=String.join(",",Collections.nCopies(ids.size(),"?"));
        String sql="SELECT DISTINCT mr.intern_profile_id,m.title FROM meeting_recipients mr JOIN meetings m ON m.id=mr.meeting_id WHERE mr.is_active=1 AND m.status='ACTIVE' AND m.meeting_date=? AND m.start_time<? AND m.end_time>? AND mr.intern_profile_id IN ("+marks+")"+(excluded==null?"":" AND m.id<>?");
        try(PreparedStatement s=c.prepareStatement(sql)){int i=1;s.setDate(i++,java.sql.Date.valueOf(date));s.setTime(i++,Time.valueOf(end));s.setTime(i++,Time.valueOf(start));for(Long id:ids)s.setLong(i++,id);if(excluded!=null)s.setLong(i,excluded);return rows(s);}
    }
    public long create(long creator,String title,LocalDate date,LocalTime start,LocalTime end,String mode,String place,String description,Collection<Long> ids,boolean hr) throws SQLException {
        try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{
            List<Map<String,Object>> people=lockAllowedInterns(c,ids,creator,hr);if(people.size()!=new HashSet<>(ids).size())throw new IllegalArgumentException("Danh sách người nhận có người ngoài phạm vi quản lý.");
            long meetingId;try(PreparedStatement s=c.prepareStatement("INSERT INTO meetings(title,meeting_date,start_time,end_time,meeting_mode,location_or_link,description,creator_user_id) VALUES(?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){setMeeting(s,title,date,start,end,mode,place,description);s.setLong(8,creator);s.executeUpdate();try(ResultSet k=s.getGeneratedKeys()){k.next();meetingId=k.getLong(1);}}
            addRecipients(c,meetingId,1,people,"INVITATION");audit(c,creator,"MEETING_CREATE",meetingId);c.commit();return meetingId;
        }catch(Exception e){c.rollback();if(e instanceof SQLException x)throw x;if(e instanceof RuntimeException x)throw x;throw new SQLException(e);}finally{c.setAutoCommit(true);}}
    }
    public void update(long id,long actor,int expectedVersion,String title,LocalDate date,LocalTime start,LocalTime end,String mode,String place,String description,Collection<Long> ids,boolean hr) throws SQLException {
        try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{
            Map<String,Object> old=lockMeeting(c,id,actor,hr);if(old==null)throw new IllegalArgumentException("Không tìm thấy lịch họp hoặc bạn không có quyền sửa.");ensureEditable(old);
            if(((Number)old.get("version_no")).intValue()!=expectedVersion)throw new IllegalArgumentException("Lịch họp vừa được người khác cập nhật. Vui lòng tải lại.");
            List<Map<String,Object>> people=lockAllowedInterns(c,ids,actor,hr);if(people.size()!=new HashSet<>(ids).size())throw new IllegalArgumentException("Danh sách người nhận có người ngoài phạm vi quản lý.");
            Set<Long> before=activeRecipientIds(c,id),after=new LinkedHashSet<>(ids);int version=expectedVersion+1;
            boolean important=!Objects.equals(old.get("title"),title)||!Objects.equals(old.get("meeting_date"),java.sql.Date.valueOf(date))||!Objects.equals(old.get("start_time"),Time.valueOf(start))||!Objects.equals(old.get("end_time"),Time.valueOf(end))||!Objects.equals(old.get("meeting_mode"),mode)||!Objects.equals(old.get("location_or_link"),place);
            try(PreparedStatement s=c.prepareStatement("UPDATE meetings SET title=?,meeting_date=?,start_time=?,end_time=?,meeting_mode=?,location_or_link=?,description=?,version_no=? WHERE id=? AND version_no=?")){setMeeting(s,title,date,start,end,mode,place,description);s.setInt(8,version);s.setLong(9,id);s.setInt(10,expectedVersion);if(s.executeUpdate()!=1)throw new IllegalArgumentException("Lịch họp vừa thay đổi. Vui lòng tải lại.");}
            Set<Long> removed=new LinkedHashSet<>(before);removed.removeAll(after);Set<Long> added=new LinkedHashSet<>(after);added.removeAll(before);Set<Long> kept=new LinkedHashSet<>(after);kept.retainAll(before);
            setInactiveAndQueue(c,id,version,removed);addRecipients(c,id,version,filter(people,added),"INVITATION");reactivate(c,id,version,filter(people,added));if(important)queueExisting(c,id,version,kept,"UPDATE");
            audit(c,actor,"MEETING_UPDATE",id);c.commit();
        }catch(Exception e){c.rollback();if(e instanceof SQLException x)throw x;if(e instanceof RuntimeException x)throw x;throw new SQLException(e);}finally{c.setAutoCommit(true);}}
    }
    public void cancel(long id,long actor,int expectedVersion,boolean hr) throws SQLException {
        try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{Map<String,Object> old=lockMeeting(c,id,actor,hr);if(old==null)throw new IllegalArgumentException("Không tìm thấy lịch họp.");ensureEditable(old);int v=expectedVersion+1;try(PreparedStatement s=c.prepareStatement("UPDATE meetings SET status='CANCELLED',version_no=? WHERE id=? AND version_no=?")){s.setInt(1,v);s.setLong(2,id);s.setInt(3,expectedVersion);if(s.executeUpdate()!=1)throw new IllegalArgumentException("Lịch họp vừa thay đổi. Vui lòng tải lại.");}queueExisting(c,id,v,activeRecipientIds(c,id),"CANCELLATION");try(PreparedStatement s=c.prepareStatement("UPDATE meeting_recipients SET is_active=0 WHERE meeting_id=?")){s.setLong(1,id);s.executeUpdate();}audit(c,actor,"MEETING_CANCEL",id);c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException x)throw x;if(e instanceof RuntimeException x)throw x;throw new SQLException(e);}finally{c.setAutoCommit(true);}}
    }
    private List<Map<String,Object>> lockAllowedInterns(Connection c,Collection<Long> ids,long user,boolean hr)throws SQLException{if(ids.isEmpty())return List.of();String marks=String.join(",",Collections.nCopies(ids.size(),"?"));String sql="SELECT ip.id,u.full_name,u.email FROM intern_profiles ip JOIN users u ON u.id=ip.user_id LEFT JOIN mentors m ON m.id=ip.mentor_id WHERE ip.internship_status='ACTIVE' AND u.status='ACTIVE' AND ip.id IN ("+marks+") AND (? OR m.user_id=?) FOR UPDATE";try(PreparedStatement s=c.prepareStatement(sql)){int i=1;for(Long id:ids)s.setLong(i++,id);s.setBoolean(i++,hr);s.setLong(i,user);return rows(s);}}
    private void addRecipients(Connection c,long meeting,int version,List<Map<String,Object>> people,String type)throws SQLException{for(Map<String,Object> p:people){long intern=((Number)p.get("id")).longValue();try(PreparedStatement s=c.prepareStatement("INSERT INTO meeting_recipients(meeting_id,intern_profile_id,recipient_name,recipient_email,is_active,last_email_status,last_email_type) VALUES(?,?,?,?,1,'PENDING',?) ON DUPLICATE KEY UPDATE recipient_name=VALUES(recipient_name),recipient_email=VALUES(recipient_email),is_active=1,last_email_status='PENDING',last_email_type=VALUES(last_email_type)")){s.setLong(1,meeting);s.setLong(2,intern);s.setString(3,String.valueOf(p.get("full_name")));s.setString(4,(String)p.get("email"));s.setString(5,type);s.executeUpdate();}queue(c,meeting,intern,version,type,(String)p.get("email"),String.valueOf(p.get("full_name")));}}
    private void queueExisting(Connection c,long meeting,int version,Collection<Long> ids,String type)throws SQLException{if(ids.isEmpty())return;String marks=String.join(",",Collections.nCopies(ids.size(),"?"));try(PreparedStatement s=c.prepareStatement("SELECT intern_profile_id,recipient_email,recipient_name FROM meeting_recipients WHERE meeting_id=? AND intern_profile_id IN ("+marks+")")){int i=1;s.setLong(i++,meeting);for(Long id:ids)s.setLong(i++,id);try(ResultSet r=s.executeQuery()){while(r.next())queue(c,meeting,r.getLong(1),version,type,r.getString(2),r.getString(3));}}try(PreparedStatement s=c.prepareStatement("UPDATE meeting_recipients SET last_email_status='PENDING',last_email_type=? WHERE meeting_id=? AND intern_profile_id IN ("+marks+")")){int i=1;s.setString(i++,type);s.setLong(i++,meeting);for(Long id:ids)s.setLong(i++,id);s.executeUpdate();}}
    private void queue(Connection c,long meeting,long intern,int version,String type,String email,String name)throws SQLException{String subject=switch(type){case"CANCELLATION"->"Lịch họp đã hủy";case"UPDATE"->"Lịch họp đã cập nhật";default->"Thư mời lịch họp";};if("UPDATE".equals(type)){try(PreparedStatement d=c.prepareStatement("DELETE FROM meeting_email_queue WHERE meeting_id=? AND intern_profile_id=? AND email_type='UPDATE' AND status='PENDING'")){d.setLong(1,meeting);d.setLong(2,intern);d.executeUpdate();}}try(PreparedStatement s=c.prepareStatement("INSERT IGNORE INTO meeting_email_queue(meeting_id,intern_profile_id,meeting_version,email_type,recipient_email,recipient_name,subject_line,status,next_attempt_at) VALUES(?,?,?,?,?,?,?,'PENDING',DATE_ADD(NOW(),INTERVAL ? MINUTE))")){s.setLong(1,meeting);s.setLong(2,intern);s.setInt(3,version);s.setString(4,type);s.setString(5,email);s.setString(6,name);s.setString(7,subject);s.setInt(8,"UPDATE".equals(type)?5:0);s.executeUpdate();}try(PreparedStatement n=c.prepareStatement("INSERT INTO notifications(user_id,title,message,target_url) SELECT user_id,?,?, '/my-calendar' FROM intern_profiles WHERE id=?")){n.setString(1,subject);n.setString(2,"Có thay đổi liên quan đến lịch họp của bạn. Mở lịch để xem chi tiết.");n.setLong(3,intern);n.executeUpdate();}}
    private void setInactiveAndQueue(Connection c,long meeting,int version,Set<Long> ids)throws SQLException{queueExisting(c,meeting,version,ids,"CANCELLATION");if(!ids.isEmpty()){String marks=String.join(",",Collections.nCopies(ids.size(),"?"));try(PreparedStatement s=c.prepareStatement("UPDATE meeting_recipients SET is_active=0 WHERE meeting_id=? AND intern_profile_id IN ("+marks+")")){int i=1;s.setLong(i++,meeting);for(Long id:ids)s.setLong(i++,id);s.executeUpdate();}}}
    private void reactivate(Connection c,long meeting,int version,List<Map<String,Object>> people)throws SQLException{/* addRecipients already reactivates */}
    private Set<Long> activeRecipientIds(Connection c,long meeting)throws SQLException{Set<Long> out=new LinkedHashSet<>();try(PreparedStatement s=c.prepareStatement("SELECT intern_profile_id FROM meeting_recipients WHERE meeting_id=? AND is_active=1")){s.setLong(1,meeting);try(ResultSet r=s.executeQuery()){while(r.next())out.add(r.getLong(1));}}return out;}
    private List<Map<String,Object>> filter(List<Map<String,Object>> people,Set<Long> ids){return people.stream().filter(p->ids.contains(((Number)p.get("id")).longValue())).toList();}
    private Map<String,Object> lockMeeting(Connection c,long id,long user,boolean hr)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT * FROM meetings WHERE id=? AND (? OR creator_user_id=?) FOR UPDATE")){s.setLong(1,id);s.setBoolean(2,hr);s.setLong(3,user);try(ResultSet r=s.executeQuery()){return r.next()?row(r):null;}}}
    private void ensureEditable(Map<String,Object> m){LocalDate d=((java.sql.Date)m.get("meeting_date")).toLocalDate();LocalTime t=((Time)m.get("end_time")).toLocalTime();if("CANCELLED".equals(m.get("status"))||LocalDateTime.of(d,t).isBefore(LocalDateTime.now()))throw new IllegalArgumentException("Lịch họp đã hủy hoặc đã kết thúc nên chỉ được xem.");}
    private void setMeeting(PreparedStatement s,String title,LocalDate date,LocalTime start,LocalTime end,String mode,String place,String desc)throws SQLException{s.setString(1,title);s.setDate(2,java.sql.Date.valueOf(date));s.setTime(3,Time.valueOf(start));s.setTime(4,Time.valueOf(end));s.setString(5,mode);s.setString(6,place);s.setString(7,desc);}
    private void audit(Connection c,long user,String action,long id)throws SQLException{try(PreparedStatement s=c.prepareStatement("INSERT INTO audit_logs(user_id,action_code,table_name,record_id,new_values_json) VALUES(?,?,'meetings',?,JSON_OBJECT('meetingId',?))")){s.setLong(1,user);s.setString(2,action);s.setLong(3,id);s.setLong(4,id);s.executeUpdate();}}
    private List<Map<String,Object>> rows(PreparedStatement s)throws SQLException{List<Map<String,Object>> out=new ArrayList<>();try(ResultSet r=s.executeQuery()){while(r.next())out.add(row(r));}return out;}
    private Map<String,Object> row(ResultSet r)throws SQLException{Map<String,Object> m=new LinkedHashMap<>();for(int i=1;i<=r.getMetaData().getColumnCount();i++)m.put(r.getMetaData().getColumnLabel(i),r.getObject(i));return m;}
}
